public RefreshFrequency xds() {
OMExplodedOrganizationSecurityGraph omGraph; OMUserRoleOrganization userRoleOrg; MyRoles roles; OMHierarchyType hierarchyType; OMHierarchyPurpose omHierarchyPurpose; MyInternalOrganizationsForRole myInternalOrganizations; MyInternalOrganizationsForRole myInternalOrganizationsPrime;
OMInternalOrganization omInternalOrg; int64 iNumRecsInserted = 0;
// insert all internal organizations that were selected from hierarchies. insert_recordset myInternalOrganizations( PartyRecId, Name, LanguageId, NameAlias, PartyNumber )
select
RecId, Name, LanguageId, NameAlias, PartyNumber
from omInternalOrg
join omGraph join userRoleOrg join roles join hierarchyType join omHierarchyPurpose
where ( (omInternalOrg.RecId == omGraph.Organization) && (userRoleOrg.omInternalOrganization == omGraph.AncestorOrganization) && (userRoleOrg.SecurityRole == roles.RoleId) && (userRoleOrg.omHierarchyType == omGraph.omHierarchyType) && (userRoleOrg.User == curUserId()) && (userRoleOrg.omHierarchyType == omHierarchyPurpose.HierarchyType) && (omHierarchyPurpose.HierarchyPurpose == HierarchyPurpose::Security) && (omGraph.ValidFrom < DateTimeUtil::utcNow()) && (omGraph.ValidTo > DateTimeUtil::utcNow()) );
iNumRecsInserted = myInternalOrganizations.RowCount();
//insert all internal organizations that were selected from flat list
insert_recordset myInternalOrganizations( PartyRecId, Name, LanguageId, NameAlias, PartyNumber )
select
RecId, Name, LanguageId, NameAlias, PartyNumber
from omInternalOrg
join omGraph join userRoleOrg join roles join hierarchyType
where ( (omInternalOrg.RecId == omGraph.Organization) && (userRoleOrg.omInternalOrganization == omGraph.AncestorOrganization) && (userRoleOrg.SecurityRole == roles.RoleId) && (userRoleOrg.User == curUserId()) && (userRoleOrg.omHierarchyType == 0)
) ;
iNumRecsInserted += myInternalOrganizations.RowCount();
//Now we need to remove duplicates - do a self join. myInternalOrganizationsPrime.linkPhysicalTableInstance(myInternalOrganizations);
delete_from myInternalOrganizations exists join myInternalOrganizationsPrime where ( (myInternalOrganizations.PartyRecId == myInternalOrganizationsPrime.PartyRecId) && (myInternalOrganizations.RecId > myInternalOrganizationsPrime.RecId) ); //duplicates have been removed.
// if no records were inserted - insert all of them. if (iNumRecsInserted == 0) { insert_recordset myInternalOrganizations( PartyRecId, Name, LanguageId, NameAlias, PartyNumber )
select
RecId, Name, LanguageId, NameAlias, PartyNumber from omInternalOrg; } return RefreshFrequency::PerInvocation; }
